code.C:
#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) == 1) {
        for (int r = 0; r < n; r++) {
            for (char c = 'a'; c <= 'z'; c++) {
                printf("%c%s", c, (c == 'z' ? "" : " "));
            }
            printf("\n");
        }
    }
    return 0;
}

